export type RateCard = {
  /** Dollars for the crew's hour, by shape; a missing row is absent. */
  rates: Partial<Record<CrewShape, number>>
  /** Dollars an hour for each person beyond two; null until the owner sets it. */
  extraPerson: number | null
  /** Percent over cost on materials; null until set, and then materials are at cost. */
  materialsMarkupPct: number | null
}

export const EMPTY_RATE_CARD: RateCard = { rates: {}, extraPerson: null, materialsMarkupPct: null }

function toCents(v: unknown): number | null {
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number(v) : NaN
  if (!Number.isFinite(n) || n < 0) return null
  return Math.round(n * 100) / 100
}

/** The card from `app_settings` rows (`key`, `value_num`): a row that is missing, null, negative or not a number is absent. */
export function rateCardFromSettings(rows: ReadonlyArray<{ key: string; value_num: unknown }>): RateCard {
  const byKey = new Map<string, number>()
  for (const r of rows) {
    const n = toCents(r.value_num)
    if (n != null) byKey.set(r.key, n)
  }
  const rates: Partial<Record<CrewShape, number>> = {}
  for (const shape of CREW_SHAPES) {
    const n = byKey.get(RATE_CARD_KEYS[shape])
    if (n != null && n > 0) rates[shape] = n
  }
  const extra = byKey.get(RATE_CARD_EXTRA_PERSON_KEY)
  const markup = byKey.get(MATERIALS_MARKUP_PCT_KEY)
  return { rates, extraPerson: extra ?? null, materialsMarkupPct: markup ?? null }
}

/** A standing from a stored value; anything unknown is `none`, so a person never prices by accident. */
export function parseChargeStanding(v: unknown): ChargeStanding {
  return typeof v === 'string' && (CHARGE_STANDINGS as readonly string[]).includes(v) ? (v as ChargeStanding) : 'none'
}

export function parseCrewShape(v: unknown): CrewShape | null {
  return typeof v === 'string' && (CREW_SHAPES as readonly string[]).includes(v) ? (v as CrewShape) : null
}

const RANK: Record<ChargeStanding, number> = { master: 3, tech: 2, helper: 1, none: 0 }

export type CrewShapeRead = {
  /** The shape of the day, from the two highest standings; null when nobody out is charged. */
  shape: CrewShape | null
  /** People beyond the two the shape names. */
  extra: number
  /** The standings that count, highest first. */
  counted: ChargeStanding[]
}

/**
 * The shape of a crew from its people's standings. `none` never counts. One person: their own row. Two or more: the
 * two highest decide — a master with anyone is a master with a helper, a tech with anyone below a master is two techs,
 * two helpers are two helpers — and everyone past two is an extra person.
 */
export function crewShapeOf(standings: ReadonlyArray<ChargeStanding>): CrewShapeRead {
  const counted = standings.filter((s) => s !== 'none').sort((a, b) => RANK[b] - RANK[a])
  if (counted.length === 0) return { shape: null, extra: 0, counted }
  if (counted.length === 1) {
    const one = counted[0]!
    return { shape: one === 'master' ? 'master_alone' : one === 'tech' ? 'tech_alone' : 'helper_alone', extra: 0, counted }
  }
  const top = counted[0]!
  const shape: CrewShape = top === 'master' ? 'master_helper' : top === 'tech' ? 'two_techs' : 'two_helpers'
  return { shape, extra: counted.length - 2, counted }
}

export type CrewRatePrice = {
  /** Dollars for the crew's hour, or null when the card has no row for it. */
  rate: number | null
  /** Why there is no rate, in words for the paper and the window. */
  why: string | null
}

/** The paper's neutral reason for a day nobody out is charged on; the office screens name who counts as nobody instead. */
export const NOBODY_CHARGED_WHY = 'Nobody out that day is charged to a customer.'

/** The rate for a shape with so many extra people, from the card; the missing row is named. */
export function crewRateFor(card: RateCard, shape: CrewShape | null, extra: number): CrewRatePrice {
  if (shape == null) return { rate: null, why: NOBODY_CHARGED_WHY }
  const base = card.rates[shape]
  if (base == null) return { rate: null, why: `The rate card has no rate for ${CREW_SHAPE_LOWER[shape]}.` }
  if (extra <= 0) return { rate: base, why: null }
  if (card.extraPerson == null) return { rate: null, why: `The rate card has no rate for each person beyond two, and this day had ${extra + 2} out.` }
  return { rate: Math.round((base + extra * card.extraPerson) * 100) / 100, why: null }
}

/** `$285.00 the crew's hour` or the missing-row words, for a chip or a line. */
export function crewRateWords(price: CrewRatePrice): string {
  if (price.rate == null) return price.why ?? 'No rate.'
  return `$${price.rate.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} the crew’s hour`
}
